class Solution {using A=array<array<long long,2>,2>;struct Seg{int n;vector<A>t;A merge(A a,A b){A c;for(int x=0;x<2;++x)for(int y=0;y<2;++y){c[x][y]=LLONG_MIN/4;for(int i=0;i<2;++i)for(int j=0;j<2;++j)if(!(i&&j))c[x][y]=max(c[x][y],a[x][i]+b[j][y]);}return c;}Seg(vector<int>&v):n(v.size()),t(4*n){build(1,0,n-1,v);}void build(int p,int l,int r,vector<int>&v){if(l==r){t[p]={{{0,LLONG_MIN/4},{LLONG_MIN/4,v[l]}}};return;}int m=(l+r)/2;build(p*2,l,m,v);build(p*2+1,m+1,r,v);t[p]=merge(t[p*2],t[p*2+1]);}void upd(int p,int l,int r,int i,int v){if(l==r){t[p]={{{0,LLONG_MIN/4},{LLONG_MIN/4,v}}};return;}int m=(l+r)/2;if(i<=m)upd(p*2,l,m,i,v);else upd(p*2+1,m+1,r,i,v);t[p]=merge(t[p*2],t[p*2+1]);}long long best(){long long a=0;for(auto row:t[1])for(long long x:row)a=max(a,x);return a;}};
 public:int maximumSumSubsequence(vector<int>& nums,vector<vector<int>>& queries){const long long MOD=1000000007;Seg s(nums);long long ans=0;for(auto&q:queries){s.upd(1,0,nums.size()-1,q[0],q[1]);ans=(ans+s.best())%MOD;}return ans;}
